'use strict';
module.exports={
 scalarPrimaryError(api){const db=new api.Database(':memory:');let stmt,close;const marker=Object.assign(Error('scalar marker'),{code:'SCALAR_MARKER'});db.function('probe',()=>{try{stmt.close()}catch(e){close={name:e.name,code:e.code,message:e.message}}throw marker});stmt=db.prepare('SELECT probe()');let primary;try{stmt.get()}catch(e){primary={same:e===marker,name:e.name,code:e.code,message:e.message}}stmt.close();db.close();return{close,primary}},
 previousStepError(api){const db=new api.Database(':memory:');db.exec('CREATE TABLE t(x UNIQUE); INSERT INTO t VALUES(1)');const stmt=db.prepare('INSERT INTO t VALUES(1)');let primary;try{stmt.get()}catch(e){primary={name:e.name,code:e.code,errcode:e.errcode,errstr:e.errstr}}let close;try{close=stmt.close()===undefined}catch(e){close={name:e.name,code:e.code,message:e.message}}stmt[Symbol.dispose]();db.close();return{primary,close}},
 receiver(api){const out=[];for(const method of [api.Statement.prototype.close,api.Statement.prototype[Symbol.dispose]])for(const receiver of [null,undefined,{},Object.create(api.Statement.prototype),1]){try{method.call(receiver);out.push('ok')}catch(e){out.push({name:e.name,code:e.code,message:e.message})}}return out},
 metadata(api){const describe=key=>{const d=Object.getOwnPropertyDescriptor(api.Statement.prototype,key);return{enumerable:d.enumerable,configurable:d.configurable,writable:d.writable,name:d.value.name,length:d.value.length}};return{close:describe('close'),dispose:describe(Symbol.dispose),distinct:api.Statement.prototype.close!==api.Statement.prototype[Symbol.dispose]}},
 close(api){const db=new api.Database(':memory:');const stmt=db.prepare('SELECT 42 AS n');stmt.close();const out=[];for(const f of [()=>stmt.get(),()=>stmt.close(),()=>stmt.columns(),()=>stmt.sourceSQL,()=>stmt.expandedSQL,()=>stmt.iterate()]){try{f();out.push('ok')}catch(e){out.push({name:e.name,code:e.code,message:e.message})}}stmt[Symbol.dispose]();db.close();return out},
 dispose(api){const db=new api.Database(':memory:');const stmt=db.prepare('SELECT 42');stmt[Symbol.dispose]();stmt[Symbol.dispose]();db.close();stmt[Symbol.dispose]();return{closed:true}},
 databaseClose(api){const db=new api.Database(':memory:');const a=db.prepare('SELECT 1'),b=db.prepare('SELECT 2');db.close();a[Symbol.dispose]();b[Symbol.dispose]();let close;try{a.close()}catch(e){close={name:e.name,code:e.code,message:e.message}}db.open();const n=db.prepare('SELECT 3 AS n').get().n;db.close();return{close,n}},
 iterator(api){const db=new api.Database(':memory:');const stmt=db.prepare('SELECT 1 AS n UNION ALL SELECT 2');const it=stmt.iterate();const first=it.next();stmt.close();const out=[];for(const f of [()=>it.next(),()=>it.return()]){try{f();out.push('ok')}catch(e){out.push({name:e.name,code:e.code,message:e.message})}}db.close();return{first,out}},
 bindingGetter(api){const db=new api.Database(':memory:');const stmt=db.prepare('SELECT :p AS n');const trace=[];const row=stmt.get({get p(){for(const f of [()=>stmt.close(),()=>stmt[Symbol.dispose]()]){try{f();trace.push('ok')}catch(e){trace.push({name:e.name,code:e.code,message:e.message})}}return 42}});stmt.close();db.close();return{trace,row}},
 scalarReentry(api){const db=new api.Database(':memory:');let stmt;const other=db.prepare('SELECT 1');const trace=[];db.function('probe',()=>{for(const f of [()=>stmt.close(),()=>stmt[Symbol.dispose](),()=>other.close(),()=>other[Symbol.dispose]()]){try{f();trace.push('ok')}catch(e){trace.push({name:e.name,code:e.code,message:e.message})}}return 42});stmt=db.prepare('SELECT probe() AS n');const row=stmt.get();stmt.close();db.close();return{trace,row}},
 finalizerReentry(api){const db=new api.Database(':memory:');let stmt,closing=false;const trace=[];db.aggregate('win',{start:0,step:(a,n)=>a+n,inverse:(a,n)=>a-n,result:a=>{if(closing){for(const f of [()=>stmt.close(),()=>stmt[Symbol.dispose]()]){try{f();trace.push('ok')}catch(e){trace.push({name:e.name,code:e.code,message:e.message})}}}return a}});stmt=db.prepare('SELECT win(x) OVER (ORDER BY x) AS n FROM (SELECT 1 x UNION ALL SELECT 2)');const it=stmt.iterate();it.next();closing=true;stmt.close();db.close();return trace},
 finalizerThrow(api){const db=new api.Database(':memory:');let closing=false;const marker=Object.assign(Error('finalizer marker'),{code:'FINALIZER_MARKER'});db.aggregate('win',{start:0,step:(a,n)=>a+n,inverse:(a,n)=>a-n,result:a=>{if(closing)throw marker;return a}});const stmt=db.prepare('SELECT win(x) OVER (ORDER BY x) AS n FROM (SELECT 1 x UNION ALL SELECT 2)');stmt.iterate().next();closing=true;let result;try{stmt.close();result={threw:false}}catch(e){result={threw:true,same:e===marker,name:e.name,code:e.code,message:e.message}}stmt[Symbol.dispose]();db.close();return result},
};
